{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver de tre betingelsesled korrekt: almindelige SU- eller slutlånsbetingelser, videregående uddannelse eller dansk EUD (herunder EUX), og varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Tillægget udbetales som tillæg til stipendium eller slutlån. Ingen af ekspertrubrikkens væsentlige fejl forekommer."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med, inklusive at tillægget udbetales sammen med SU-stipendium eller slutlån. Svaret nævner også EUX, som er et supporting element."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en direkte opregning af betingelserne og besvarer spørgsmålet uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til en identificerbar kilde: vejledningens afsnit 3.1–3.3."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledningens afsnit 3.1–3.3 findes blandt de frosne kilder og er autoritative og anvendelige til spørgsmålet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Afsnit 3.1–3.3 understøtter de to første led og EUD/EUX. Den varige funktionsnedsættelse med meget betydelige begrænsninger står i afsnit 3.1, så det led er dækket. Udsagnet om, at tillægget udbetales som tillæg til SU-stipendiet eller slutlånet, støttes af afsnit 3.2.1, som ligger inden for den angivne henvisning. Der er dog en svaghed: henvisningen er bred og citerer ikke bestemte passager. Udsagnet om, at man skal 'gennemgå' en SU-berettigende uddannelse, og at man 'skal have ret til SU', støttes af 3.2.1. Kildestøtten er samlet set tilstrækkelig, så dette kriterium vurderes ikke som fejlet."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen regler, betingelser eller undtagelser, som ikke er understøttet af materialet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den eneste krævede kvalifikation er, at svaret er et overblik uden udtømmende gengivelse af de almindelige SU-betingelser, og det kræver ingen særskilt advarsel. Svaret bruger 'herunder' og antyder dermed, at opregningen ikke er udtømmende."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en sammenhængende opregning af betingelserne uden indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal' bruges om betingelserne, hvilket svarer til kilden ('For at få handicaptillæg skal ...'). Der er ingen skøn eller undtagelser, der gøres absolutte."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Svaret nævner, at man skal opfylde de almindelige betingelser for at få SU eller slutlån."
    },
    "A2": {
      "label": "yes",
      "reason": "Svaret kræver, at man går på en videregående uddannelse eller en dansk EUD, herunder EUX."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret nævner en varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret nævner at have ret til SU og være indskrevet på og gennemgå en SU-berettigende uddannelse."
    },
    "A6": {
      "label": "partial",
      "reason": "Svaret nævner EUD og EUX, men ikke at erhvervslignende uddannelse uden for Danmark er udelukket."
    }
  },
  "overall_notes": "Svaret er juridisk korrekt og dækker alle tre kritiske betingelsesled samt EUX. Det udelader supporting-elementet om erhvervslignende uddannelse i udlandet. Kildehenvisningen er kun et afsnitsspænd, men støtter indholdet. Jeg har i C06 skrevet 'not_met' ved en fejl i forhold til min egen begrundelse; begrundelsen konkluderer, at støtten er tilstrækkelig, så den korrekte label er 'met'."
}

